#!/bin/sh
#
# Xcode Cloud post-clone hook.
#
# This repo is a **managed (CNG) Expo project**: `ios/` and `android/` are
# gitignored and generated by `expo prebuild`, so what Xcode Cloud clones has no
# Xcode project in it at all. Everything the build needs is produced here.
#
# Xcode Cloud runs this from `ci_scripts/`, before dependency resolution and
# before the build, which is exactly the window we need.
#
# NOTE: untested in Xcode Cloud itself — written against the documented runner
# environment. The first CI run is the real test; see docs/xcode-cloud.md for
# what to check if a step fails.

set -e

cd "$CI_PRIMARY_REPOSITORY_PATH"

echo "--- Node ---"
# Xcode Cloud runners ship no Node. Homebrew is available.
brew install node@22
export PATH="/opt/homebrew/opt/node@22/bin:$PATH"
node -v
npm -v

echo "--- CocoaPods ---"
# The runner's bundled CocoaPods can lag; install explicitly so the version is
# predictable. UTF-8 matters: CocoaPods crashes on an ASCII-8BIT locale when it
# normalises the project path.
brew install cocoapods
export LANG=en_US.UTF-8
export LC_ALL=en_US.UTF-8
pod --version

echo "--- JS dependencies ---"
npm ci

echo "--- Build number ---"
# The build number is baked into Info.plist when the project is generated, so it
# has to be set before prebuild runs.
#
# IMPORTANT: this app already has TestFlight builds from EAS, and Xcode Cloud's
# CI_BUILD_NUMBER restarts at 1 for a new workflow. App Store Connect rejects an
# upload whose build number is not higher than the last one for that version, so
# a fresh workflow would be rejected immediately. Set BUILD_NUMBER_OFFSET as a
# workflow variable to something above the highest existing EAS build number.
if [ -n "$CI_BUILD_NUMBER" ]; then
  OFFSET="${BUILD_NUMBER_OFFSET:-0}"
  RESOLVED=$((CI_BUILD_NUMBER + OFFSET))
  RESOLVED="$RESOLVED" node -e "
    const fs = require('fs');
    const p = 'app.json';
    const c = JSON.parse(fs.readFileSync(p, 'utf8'));
    c.expo.ios = c.expo.ios || {};
    c.expo.ios.buildNumber = String(process.env.RESOLVED);
    fs.writeFileSync(p, JSON.stringify(c, null, 2) + '\n');
    console.log('buildNumber =', c.expo.ios.buildNumber);
  "
fi

echo "--- iOS project ---"
# Works whether or not ios/ is committed. If it is present (the recommended
# setup, so Xcode Cloud can discover the scheme at clone time), leave it alone —
# regenerating would discard any native changes made in Xcode.
if [ -d "ios" ]; then
  echo "ios/ is committed; skipping prebuild"
else
  echo "ios/ not in the repo; generating it"
  npx expo prebuild --platform ios --no-install
fi

echo "--- Mapbox SDK credentials (only if configured) ---"
# @rnmapbox/maps pulls the Mapbox SDK from a private CocoaPods source on some
# versions. It resolves without credentials on this project today, so this is
# conditional rather than required — set MAPBOX_DOWNLOADS_TOKEN (an `sk.` token)
# as a secret workflow variable only if pod install starts 401ing on MapboxMaps.
if [ -n "$MAPBOX_DOWNLOADS_TOKEN" ]; then
  echo "machine api.mapbox.com login mapbox password $MAPBOX_DOWNLOADS_TOKEN" > "$HOME/.netrc"
  chmod 600 "$HOME/.netrc"
  echo "wrote ~/.netrc"
else
  echo "MAPBOX_DOWNLOADS_TOKEN not set — skipping (fine unless pod install 401s)"
fi

echo "--- Pods ---"
cd ios
pod install

echo "--- post-clone complete ---"
